import axios from "axios";
import MaterialTable, { MTableToolbar } from "material-table";
import React, { Component } from "react";
import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";
import { changePage } from "../../actions/pageActions";
import Checkbox from "@material-ui/core/Checkbox";

class Clients extends Component {
  state = {
    rowData: [],
    tableLoaded: true,
    showDeletes: false
  };

  componentDidMount() {
    this.retrieveFromDb();
  }

  retrieveFromDb = () => {
    this.setState(state => ({
      tableLoaded: false,
      rowData: state.rowData
    }));
    axios
      .get("/api/userAccessTypes")
      .then(res => {
        var rowData;
        if (!this.state.showDeletes) {
          rowData = res.data.filter((x, index) => {
            return x.deletedAt == null;
          });
        }
        /*var rowData = res.data.filter((x, index) => {
          return x.deletedAt == null;
        });*/
        rowData = rowData.map((x, index) => {
          return {
            id: x._id,
            name: x.name,
            deletedAt: x.deletedAt
          };
        });

        this.setState(state => ({
          tableLoaded: true,
          rowData
        }));
      })
      .catch(err => console.log(err));
  };

  onPageChangeClick = (navType, page) => {
    const pageDetail = {
      navType,
      page
    };
    this.props.changePage(pageDetail);
  };

  showDeletes = () => {
    this.setState(
      state => ({
        showDeletes: !state.showDeletes
      }),
      () => this.retrieveFromDb()
    );
  };
  render() {
    return (
      <div>
        {this.state.tableLoaded ? (
          <MaterialTable
            columns={[
              { title: "ID", field: "id", editable: "never" },
              { title: "Name", field: "name" }
            ]}
            data={this.state.rowData}
            title="Create New User Access"
            options={{
              actionsColumnIndex: 2,
              addRowPosition: "first",
              exportButton: true,
              exportFileName: "UserAccessTypes"
            }}
            onRowClick={(rowdata, event) => {
              //console.log(event.id);
              this.onPageChangeClick("ClientsNav", event.id);
            }}
            components={{
              Toolbar: props => (
                <div>
                  <MTableToolbar {...props} />
                  <div className="ml-3">
                    <Checkbox value="top" onChange={this.showDeletes} />
                    {""}
                    Show Deletions
                  </div>
                </div>
              )
            }}
            editable={{
              onRowAdd: newData =>
                new Promise((resolve, reject) => {
                  setTimeout(() => {
                    {
                      this.setState(state => ({
                        tableLoaded: false,
                        rowData: state.rowData
                      }));
                      const newClient = {
                        name: newData.name
                      };
                      axios
                        .post(
                          "/api/userAccessTypes",
                          newClient,
                          tokenConfig(store.getState)
                        )
                        .then(res => {
                          console.log(res.data);
                          this.retrieveFromDb();
                          this.setState(state => ({
                            tableLoaded: true,
                            rowData: state.rowData
                          }));
                        })
                        .catch(err => console.log(err.data));
                    }
                    resolve();
                  }, 10);
                }),
              onRowUpdate: (newData, oldData) =>
                new Promise((resolve, reject) => {
                  setTimeout(() => {
                    {
                      this.setState(state => ({
                        tableLoaded: false,
                        rowData: state.rowData
                      }));
                      axios
                        .put(
                          `/api/userAccessTypes/${newData.id}`,
                          { name: newData.name },
                          tokenConfig(store.getState)
                        )
                        .then(res => {
                          console.log(res.data);
                          this.retrieveFromDb();
                          this.setState(state => ({
                            tableLoaded: true,
                            rowData: state.rowData
                          }));
                        })
                        .catch(err => console.log(err.data));
                    }
                    resolve();
                  }, 1000);
                }),
              onRowDelete: oldData =>
                new Promise((resolve, reject) => {
                  setTimeout(() => {
                    {
                      this.setState(state => ({
                        tableLoaded: false,
                        rowData: state.rowData
                      }));
                      axios
                        .delete(
                          `/api/userAccessTypes/${oldData.id}`,
                          tokenConfig(store.getState)
                        )
                        .then(res => {
                          console.log(res.data);
                          this.retrieveFromDb();
                          this.setState(state => ({
                            tableLoaded: true,
                            rowData: state.rowData
                          }));
                        })
                        .catch(err => console.log(err.data));
                    }
                    resolve();
                  }, 1000);
                })
            }}
            //////
          />
        ) : (
          <div
            style={{
              display: "flex",
              justifyContent: "center"
            }}
          >
            <Spinner animation="border" />
          </div>
        )}
      </div>
    );
  }
}

const mapStateToProps = state => ({
  auth: state.auth
});

export default connect(mapStateToProps, { changePage })(Clients);
